(window.ABDI_PAKET = window.ABDI_PAKET || {})["skd.tkp.anti-radikalisme.1"] = [{"i":2719,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda menemukan akun media sosial yang mengajak menolak Pancasila dan membenarkan kekerasan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak ikut menyebarkan, melaporkan akun itu melalui kanal resmi, dan mengingatkan orang terdekat agar tidak terpengaruh.” Mencegah penyebaran paham kekerasan.\nPilihan terendah (nilai 1): “Mengikuti dan menyukai unggahannya karena menarik.” Mendukung paham radikal.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Tidak ikut menyebarkan, melaporkan akun itu melalui kanal resmi, dan mengingatkan orang terdekat agar tidak terpengaruh.","Melaporkan akun tersebut ke platform media sosial.","Membagikannya ke grup untuk menanyakan pendapat orang lain.","Mengikuti dan menyukai unggahannya karena menarik.","Mengabaikan dan tidak membuka akun itu lagi."],"s":[5,4,2,1,3],"w":["Mencegah penyebaran paham kekerasan.","Tepat, tetapi terbatas.","Ikut memperluas jangkauannya.","Mendukung paham radikal.","Aman, tetapi pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2720,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang kenalan mengajak Anda bergabung dengan kelompok yang ingin mengganti dasar negara. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dengan tegas, menjelaskan pentingnya Pancasila, dan melapor ke pihak berwenang bila ada ancaman nyata.” Teguh pada Pancasila dan mencegah bahaya.\nPilihan terendah (nilai 1): “Menerima ajakan itu karena penasaran.” Terlibat paham radikal.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menolak ajakan itu dengan tegas.","Menerima ajakan itu karena penasaran.","Menolak secara halus agar hubungan tetap baik.","Mengatakan akan mempertimbangkannya.","Menolak dengan tegas, menjelaskan pentingnya Pancasila, dan melapor ke pihak berwenang bila ada ancaman nyata."],"s":[4,1,3,2,5],"w":["Tegas.","Terlibat paham radikal.","Menolak, tetapi kurang tegas.","Membuka peluang.","Teguh pada Pancasila dan mencegah bahaya."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2721,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Rekan kerja Anda sering menyebarkan konten yang merendahkan kelompok agama lain. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengajaknya berdiskusi secara pribadi tentang dampak konten itu dan pentingnya menghargai keberagaman.” Persuasif dan mendidik.\nPilihan terendah (nilai 1): “Ikut menyebarkan konten tersebut.” Ikut menyebarkan kebencian.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menegurnya agar berhenti menyebarkan konten tersebut.","Mendiamkannya karena takut berselisih.","Mengajaknya berdiskusi secara pribadi tentang dampak konten itu dan pentingnya menghargai keberagaman.","Ikut menyebarkan konten tersebut.","Melaporkannya kepada atasan."],"s":[4,2,5,1,3],"w":["Tegas, tetapi kurang persuasif.","Membiarkan.","Persuasif dan mendidik.","Ikut menyebarkan kebencian.","Prosedural."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2722,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Di lingkungan Anda ada kegiatan kelompok yang mengajarkan kebencian terhadap pemerintah dan kelompok lain. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Berkoordinasi dengan tokoh masyarakat dan aparat setempat untuk menyikapinya, sambil mengajak warga memperkuat kegiatan yang menyejukkan.” Ditangani bersama dan dicegah meluas.\nPilihan terendah (nilai 1): “Ikut hadir dan mendukung isi ajarannya.” Mendukung paham radikal.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Melarang keluarga Anda mengikuti kegiatan tersebut.","Membiarkannya selama tidak mengganggu Anda.","Ikut hadir dan mendukung isi ajarannya.","Berkoordinasi dengan tokoh masyarakat dan aparat setempat untuk menyikapinya, sambil mengajak warga memperkuat kegiatan yang menyejukkan.","Melaporkannya kepada ketua RT atau aparat setempat."],"s":[3,2,1,5,4],"w":["Hanya melindungi keluarga sendiri.","Abai.","Mendukung paham radikal.","Ditangani bersama dan dicegah meluas.","Tepat, tanpa langkah pencegahan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2723,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda menerima pesan berantai yang mengajak warga tidak mematuhi hukum negara. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak meneruskan pesan itu, mengklarifikasi kepada pengirim, dan menjelaskan bahwa hukum negara melindungi semua warga.” Memutus penyebaran dan meluruskan.\nPilihan terendah (nilai 1): “Meneruskan pesan itu ke semua kontak.” Menyebarkan ajakan melanggar hukum.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menyimpan pesan itu tanpa menanggapinya.","Meneruskan pesan itu sambil menulis bahwa Anda belum tentu setuju.","Tidak meneruskan pesan itu dan menghapusnya.","Tidak meneruskan pesan itu, mengklarifikasi kepada pengirim, dan menjelaskan bahwa hukum negara melindungi semua warga.","Meneruskan pesan itu ke semua kontak."],"s":[3,2,4,5,1],"w":["Pasif.","Tetap menyebarkan.","Memutus penyebaran.","Memutus penyebaran dan meluruskan.","Menyebarkan ajakan melanggar hukum."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2724,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang siswa bertanya kepada Anda mengapa Indonesia memakai Pancasila sebagai dasar negara. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan sejarah dan nilai Pancasila sebagai kesepakatan bersama yang menyatukan bangsa yang beragam.” Mendidik dan menanamkan nilai kebangsaan.\nPilihan terendah (nilai 1): “Mengatakan bahwa Pancasila sebenarnya sudah tidak relevan.” Melemahkan ideologi negara.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Mengatakan bahwa itu sudah ketentuan negara.","Mengatakan bahwa Pancasila sebenarnya sudah tidak relevan.","Mengalihkan pembicaraan karena topiknya sensitif.","Menyarankannya membaca buku sejarah tentang Pancasila.","Menjelaskan sejarah dan nilai Pancasila sebagai kesepakatan bersama yang menyatukan bangsa yang beragam."],"s":[3,1,2,4,5],"w":["Kurang menjelaskan.","Melemahkan ideologi negara.","Menghindar.","Membantu, tetapi tidak langsung.","Mendidik dan menanamkan nilai kebangsaan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2725,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda melihat poster di fasilitas umum yang mengajak orang bergabung dengan kelompok bersenjata. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mendokumentasikan dan melaporkannya kepada aparat berwenang agar segera ditangani.” Tindakan cepat melalui jalur yang tepat.\nPilihan terendah (nilai 1): “Memotret poster itu lalu menyebarkannya di media sosial tanpa keterangan.” Ikut menyebarkan ajakan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Mencopot poster itu sendiri tanpa melapor.","Mendokumentasikan dan melaporkannya kepada aparat berwenang agar segera ditangani.","Membiarkannya karena mengira sudah ada yang melapor.","Memotret poster itu lalu menyebarkannya di media sosial tanpa keterangan.","Melaporkannya kepada pengelola fasilitas."],"s":[3,5,2,1,4],"w":["Masalah hilang sementara, sumbernya tidak ditangani.","Tindakan cepat melalui jalur yang tepat.","Abai.","Ikut menyebarkan ajakan.","Tepat, tetapi tidak langsung ke aparat."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2726,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Teman Anda mulai menutup diri dan menganggap semua orang di luar kelompoknya sebagai musuh. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tetap menjalin komunikasi, mengajaknya berdialog dengan pikiran terbuka, dan melibatkan keluarga atau tokoh yang ia percayai.” Merangkul dan mencegah radikalisasi.\nPilihan terendah (nilai 1): “Ikut membenarkan pandangannya agar ia tidak menjauh.” Mendukung pandangan intoleran.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Ikut membenarkan pandangannya agar ia tidak menjauh.","Membicarakan perubahan sikapnya kepada orang lain.","Menjaga jarak darinya.","Menasihatinya agar tidak berpikiran sempit.","Tetap menjalin komunikasi, mengajaknya berdialog dengan pikiran terbuka, dan melibatkan keluarga atau tokoh yang ia percayai."],"s":[1,2,3,4,5],"w":["Mendukung pandangan intoleran.","Tidak membantu.","Membiarkannya makin tertutup.","Peduli, tetapi kurang mendalam.","Merangkul dan mencegah radikalisasi."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2727,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Dalam diskusi daring, seseorang menyatakan kekerasan boleh dipakai untuk mencapai tujuan kelompoknya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menanggapi dengan tenang memakai argumen hukum dan nilai kemanusiaan, lalu melaporkan unggahan yang menghasut.” Melawan narasi kekerasan dengan bijak.\nPilihan terendah (nilai 1): “Mendukung pendapat itu karena tujuannya dianggap baik.” Membenarkan kekerasan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menyatakan tidak setuju dengan pendapat tersebut.","Menanggapi dengan tenang memakai argumen hukum dan nilai kemanusiaan, lalu melaporkan unggahan yang menghasut.","Mendukung pendapat itu karena tujuannya dianggap baik.","Keluar dari diskusi itu.","Diam saja dan terus membaca diskusi."],"s":[4,5,1,3,2],"w":["Menolak, tanpa tindak lanjut.","Melawan narasi kekerasan dengan bijak.","Membenarkan kekerasan.","Menghindar.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2942,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang rekan menolak mengikuti upacara bendera karena menganggapnya bertentangan dengan keyakinannya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengajaknya berdialog dengan tenang tentang makna upacara sebagai penghormatan kepada negara, bukan ibadah, dan melibatkan pembimbing bila perlu.” Meluruskan dengan dialog.\nPilihan terendah (nilai 1): “Ikut tidak mengikuti upacara karena menurut Anda alasannya masuk akal dan tidak ada sanksi tegas.” Ikut melemahkan penghormatan kepada negara.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menghindari membahas hal itu dengannya.","Membiarkannya karena itu urusan pribadi.","Ikut tidak mengikuti upacara karena menurut Anda alasannya masuk akal dan tidak ada sanksi tegas.","Mengajaknya berdialog dengan tenang tentang makna upacara sebagai penghormatan kepada negara, bukan ibadah, dan melibatkan pembimbing bila perlu.","Mengingatkannya bahwa upacara bendera adalah kewajiban ASN."],"s":[2,3,1,5,4],"w":["Menghindar.","Pasif.","Ikut melemahkan penghormatan kepada negara.","Meluruskan dengan dialog.","Tegas, kurang dialog."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2943,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda menemukan buku di perpustakaan kantor yang berisi ajakan memusuhi kelompok lain. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengamankan buku itu dan melaporkannya kepada pengelola perpustakaan serta atasan untuk ditindaklanjuti.” Mencegah penyebaran paham kebencian.\nPilihan terendah (nilai 1): “Meminjamkan buku itu kepada rekan supaya mereka bisa menilai sendiri isinya, karena menurut Anda setiap orang berhak membaca apa saja.” Ikut menyebarkan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Membiarkannya di rak.","Meminjamkan buku itu kepada rekan supaya mereka bisa menilai sendiri isinya, karena menurut Anda setiap orang berhak membaca apa saja.","Memindahkan buku itu dari rak.","Mengamankan buku itu dan melaporkannya kepada pengelola perpustakaan serta atasan untuk ditindaklanjuti.","Pura-pura tidak melihat."],"s":[3,1,4,5,2],"w":["Pasif.","Ikut menyebarkan.","Mencegah, belum dilaporkan.","Mencegah penyebaran paham kebencian.","Abai."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2944,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang tokoh dalam kajian mingguan di lingkungan Anda mengajarkan bahwa pemerintah adalah musuh yang boleh dilawan dengan kekerasan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak terpengaruh, mengajak warga berdiskusi dengan rujukan yang benar, dan melaporkan ajakan kekerasan itu kepada aparat berwenang.” Melawan ajakan kekerasan lewat jalur yang benar.\nPilihan terendah (nilai 1): “Mendukung ajaran itu karena menurut Anda pemerintah memang sering mengecewakan rakyat.” Membenarkan kekerasan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Tidak terpengaruh, mengajak warga berdiskusi dengan rujukan yang benar, dan melaporkan ajakan kekerasan itu kepada aparat berwenang.","Mendukung ajaran itu karena menurut Anda pemerintah memang sering mengecewakan rakyat.","Berhenti mengikuti kajian itu dan mengingatkan keluarga.","Tetap ikut tanpa menanggapi.","Menghindari membicarakannya dengan siapa pun."],"s":[5,1,4,3,2],"w":["Melawan ajakan kekerasan lewat jalur yang benar.","Membenarkan kekerasan.","Menjaga diri dan keluarga.","Pasif dan berisiko.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2945,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Ada penggalangan dana di grup percakapan yang tujuannya tidak jelas dan menyebut \"perjuangan bersenjata\". Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak menyumbang, menyimpan bukti, dan melaporkannya kepada aparat berwenang.” Memutus pendanaan kekerasan.\nPilihan terendah (nilai 1): “Menyumbang sedikit karena penggalangnya mengatakan dana itu untuk membantu saudara yang tertindas.” Mendanai kekerasan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menyumbang sedikit karena penggalangnya mengatakan dana itu untuk membantu saudara yang tertindas.","Tidak menyumbang, menyimpan bukti, dan melaporkannya kepada aparat berwenang.","Tidak menyumbang dan keluar dari grup.","Menanyakan tujuan dana itu dulu sebelum memutuskan.","Tidak menyumbang dan tetap di grup."],"s":[1,5,4,2,3],"w":["Mendanai kekerasan.","Memutus pendanaan kekerasan.","Menjaga diri.","Ragu terhadap hal yang jelas berbahaya.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2946,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Keponakan remaja Anda mulai aktif di forum daring yang memuja pelaku teror. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mendekatinya dengan hangat, mengajaknya berdiskusi, memberi bacaan pembanding, dan melibatkan orang tuanya serta konselor bila perlu.” Merangkul dan mencegah radikalisasi.\nPilihan terendah (nilai 1): “Memarahinya di depan keluarga besar dan menyita ponselnya tanpa penjelasan, supaya ia kapok membuka forum itu.” Bisa membuatnya makin tertutup.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Memarahinya di depan keluarga besar dan menyita ponselnya tanpa penjelasan, supaya ia kapok membuka forum itu.","Mendekatinya dengan hangat, mengajaknya berdiskusi, memberi bacaan pembanding, dan melibatkan orang tuanya serta konselor bila perlu.","Menasihatinya sekali.","Membiarkannya karena masih remaja.","Memberi tahu orang tuanya."],"s":[1,5,3,2,4],"w":["Bisa membuatnya makin tertutup.","Merangkul dan mencegah radikalisasi.","Kurang tuntas.","Abai.","Tepat, kurang pendekatan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2947,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang pegawai baru menolak berbicara dengan rekan yang berbeda keyakinan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengajaknya berbincang tentang nilai kebersamaan di tempat kerja dan membantunya membangun hubungan baik dengan semua rekan.” Merangkul.\nPilihan terendah (nilai 1): “Mendukung sikapnya karena menurut Anda setiap orang bebas memilih teman bicara, termasuk di kantor.” Membiarkan intoleransi.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Mengajaknya berbincang tentang nilai kebersamaan di tempat kerja dan membantunya membangun hubungan baik dengan semua rekan.","Menjauhinya.","Membiarkannya.","Mengingatkannya bahwa ASN harus bersikap adil kepada semua rekan.","Mendukung sikapnya karena menurut Anda setiap orang bebas memilih teman bicara, termasuk di kantor."],"s":[5,2,3,4,1],"w":["Merangkul.","Menghindar.","Pasif.","Tepat.","Membiarkan intoleransi."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2948,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Warga menolak kembalinya mantan narapidana terorisme yang sudah menjalani program deradikalisasi. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Membantu memfasilitasi dialog antara warga, aparat, dan pendamping program supaya ia bisa diterima dan diawasi bersama.” Mendukung reintegrasi yang aman.\nPilihan terendah (nilai 1): “Ikut mengusirnya dari kampung karena khawatir ia kembali melakukan aksi, walaupun ia sudah menyelesaikan hukuman dan pembinaan.” Stigma yang bisa mendorong radikalisasi ulang.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menghindari pembahasan itu.","Menjelaskan kepada warga bahwa ia sudah menjalani pembinaan.","Membantu memfasilitasi dialog antara warga, aparat, dan pendamping program supaya ia bisa diterima dan diawasi bersama.","Menyerahkan urusan itu kepada aparat.","Ikut mengusirnya dari kampung karena khawatir ia kembali melakukan aksi, walaupun ia sudah menyelesaikan hukuman dan pembinaan."],"s":[2,4,5,3,1],"w":["Menghindar.","Membantu.","Mendukung reintegrasi yang aman.","Pasif.","Stigma yang bisa mendorong radikalisasi ulang."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2949,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Dalam rapat warga ada usulan melarang pendatang yang berbeda agama tinggal di kampung. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikan bahwa setiap warga negara berhak tinggal di mana pun sesuai hukum, dan mengajak warga menolak usulan diskriminatif itu.” Membela hak warga negara.\nPilihan terendah (nilai 1): “Mendukung usulan itu supaya kampung tetap tenteram dan tidak ada perbedaan yang bisa memicu masalah di kemudian hari, apalagi banyak warga lain juga setuju.” Diskriminatif.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Mendukung usulan itu supaya kampung tetap tenteram dan tidak ada perbedaan yang bisa memicu masalah di kemudian hari, apalagi banyak warga lain juga setuju.","Abstain.","Menolak usulan itu.","Tidak hadir di rapat berikutnya.","Menyampaikan bahwa setiap warga negara berhak tinggal di mana pun sesuai hukum, dan mengajak warga menolak usulan diskriminatif itu."],"s":[1,3,4,2,5],"w":["Diskriminatif.","Pasif.","Tepat.","Menghindar.","Membela hak warga negara."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2950,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda melihat mural di tembok kampung yang memuat simbol organisasi terlarang. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mendokumentasikan dan melaporkannya kepada perangkat desa dan aparat supaya ditangani sesuai prosedur.” Tanggap dan sesuai jalur.\nPilihan terendah (nilai 1): “Memotret mural itu dan mengunggahnya ke media sosial dengan komentar kagum karena menurut Anda gambarnya bagus.” Ikut menyebarkan simbol terlarang.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Memberi tahu ketua RT.","Menghapus mural itu sendiri tanpa melapor.","Mendokumentasikan dan melaporkannya kepada perangkat desa dan aparat supaya ditangani sesuai prosedur.","Memotret mural itu dan mengunggahnya ke media sosial dengan komentar kagum karena menurut Anda gambarnya bagus.","Membiarkannya."],"s":[4,2,5,1,3],"w":["Membantu.","Masalah tidak tertangani.","Tanggap dan sesuai jalur.","Ikut menyebarkan simbol terlarang.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2951,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang dosen di kampus adik Anda mengajarkan bahwa demokrasi bertentangan dengan agama dan harus ditolak. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengajak adik berdiskusi kritis dengan rujukan yang benar, dan menyarankannya menyampaikan keberatan lewat jalur kampus.” Membangun daya kritis.\nPilihan terendah (nilai 1): “Mendukung pendapat dosen itu karena menurut Anda demokrasi memang banyak kekurangannya dan perlu diganti dengan sistem yang menurut dosen itu lebih sesuai.” Mendukung paham anti-Pancasila.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Mendukung pendapat dosen itu karena menurut Anda demokrasi memang banyak kekurangannya dan perlu diganti dengan sistem yang menurut dosen itu lebih sesuai.","Menyarankan adik pindah kampus.","Membiarkan adik menilai sendiri.","Menasihati adik supaya tidak mudah terpengaruh.","Mengajak adik berdiskusi kritis dengan rujukan yang benar, dan menyarankannya menyampaikan keberatan lewat jalur kampus."],"s":[1,2,3,4,5],"w":["Mendukung paham anti-Pancasila.","Menghindar.","Pasif.","Peduli.","Membangun daya kritis."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2952,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Video ceramah yang menghasut kekerasan terhadap kelompok tertentu beredar di grup keluarga. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak meneruskannya, menjelaskan bahayanya kepada keluarga dengan santun, dan melaporkan konten itu ke platform.” Memutus penyebaran.\nPilihan terendah (nilai 1): “Meneruskan video itu ke grup lain karena menurut Anda isinya menyuarakan keresahan banyak orang dan perlu didengar oleh pemerintah.” Menyebarkan hasutan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Tidak meneruskan video itu.","Tidak meneruskannya, menjelaskan bahayanya kepada keluarga dengan santun, dan melaporkan konten itu ke platform.","Membiarkannya.","Keluar dari grup keluarga.","Meneruskan video itu ke grup lain karena menurut Anda isinya menyuarakan keresahan banyak orang dan perlu didengar oleh pemerintah."],"s":[4,5,3,2,1],"w":["Benar, pasif.","Memutus penyebaran.","Pasif.","Menghindar.","Menyebarkan hasutan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2953,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Sekelompok orang tanpa kewenangan melakukan razia terhadap usaha warga dengan alasan moral. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak terlibat, mengamankan diri, dan segera melaporkannya kepada aparat berwenang.” Menegakkan hukum lewat jalur resmi.\nPilihan terendah (nilai 1): “Ikut dalam razia itu karena tujuannya dianggap baik untuk menjaga moral warga dan aparat setempat jarang bertindak.” Main hakim sendiri.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Melaporkannya kepada ketua RT.","Menonton dari jauh.","Menutup usaha sendiri supaya tidak didatangi.","Tidak terlibat, mengamankan diri, dan segera melaporkannya kepada aparat berwenang.","Ikut dalam razia itu karena tujuannya dianggap baik untuk menjaga moral warga dan aparat setempat jarang bertindak."],"s":[4,3,2,5,1],"w":["Membantu.","Pasif.","Menghindar.","Menegakkan hukum lewat jalur resmi.","Main hakim sendiri."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2954,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang rekan kerja mengunggah dukungan untuk kelompok teror di luar negeri. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengingatkannya secara pribadi tentang bahaya dan pelanggarannya, dan melaporkannya kepada atasan sesuai prosedur.” Tegas dan sesuai jalur.\nPilihan terendah (nilai 1): “Menyukai unggahan itu karena menurut Anda kelompok itu membela orang-orang yang tertindas di negaranya dan media jarang memberitakan sisi mereka.” Mendukung terorisme.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Berhenti mengikuti akunnya.","Mengingatkannya untuk menghapus unggahan itu.","Menyukai unggahan itu karena menurut Anda kelompok itu membela orang-orang yang tertindas di negaranya dan media jarang memberitakan sisi mereka.","Mengingatkannya secara pribadi tentang bahaya dan pelanggarannya, dan melaporkannya kepada atasan sesuai prosedur.","Diam saja."],"s":[2,4,1,5,3],"w":["Menghindar.","Peduli, belum ditindaklanjuti.","Mendukung terorisme.","Tegas dan sesuai jalur.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2955,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang siswa di sekolah tempat Anda mengajar menolak hormat kepada bendera saat upacara. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengajaknya berbicara secara personal, menjelaskan makna penghormatan kepada bendera, dan berkoordinasi dengan orang tuanya.” Mendidik dengan merangkul.\nPilihan terendah (nilai 1): “Menghukumnya di depan teman-temannya supaya siswa lain tidak mencontoh, walaupun alasan penolakannya belum diketahui dan orang tuanya belum dihubungi.” Bisa memperkuat sikapnya.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Membiarkannya.","Mengajaknya berbicara secara personal, menjelaskan makna penghormatan kepada bendera, dan berkoordinasi dengan orang tuanya.","Melaporkannya kepada kepala sekolah tanpa berbicara dengannya.","Menegurnya dengan lembut.","Menghukumnya di depan teman-temannya supaya siswa lain tidak mencontoh, walaupun alasan penolakannya belum diketahui dan orang tuanya belum dihubungi."],"s":[3,5,2,4,1],"w":["Pasif.","Mendidik dengan merangkul.","Kurang mendidik.","Tepat.","Bisa memperkuat sikapnya."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2956,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda diminta menjadi narasumber sosialisasi moderasi beragama di kelurahan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyiapkan materi dengan rujukan yang benar, contoh nyata, dan memberi ruang tanya jawab.” Menyebarkan nilai kebangsaan.\nPilihan terendah (nilai 1): “Memakai forum itu untuk menyudutkan kelompok tertentu yang menurut Anda paling sering membuat masalah.” Memecah belah.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menolak karena topiknya sensitif.","Menyarankan narasumber lain.","Memakai forum itu untuk menyudutkan kelompok tertentu yang menurut Anda paling sering membuat masalah.","Menerima tugas dan menyampaikan materi dari bahan yang ada.","Menyiapkan materi dengan rujukan yang benar, contoh nyata, dan memberi ruang tanya jawab."],"s":[2,3,1,4,5],"w":["Menghindar.","Melempar.","Memecah belah.","Bertanggung jawab.","Menyebarkan nilai kebangsaan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2957,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang kenalan mengajak Anda ikut pelatihan bela diri yang ternyata diisi doktrin melawan negara. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak ikut, menjauhi kegiatan itu, dan melaporkannya kepada aparat berwenang.” Menolak dan melapor.\nPilihan terendah (nilai 1): “Ikut karena latihannya gratis dan menurut Anda doktrinnya tidak akan memengaruhi Anda.” Ikut terpapar paham radikal.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menolak tanpa penjelasan.","Ikut sekali untuk melihat-lihat.","Ikut karena latihannya gratis dan menurut Anda doktrinnya tidak akan memengaruhi Anda.","Menolak ikut dan memperingatkan keluarga.","Menolak ikut, menjauhi kegiatan itu, dan melaporkannya kepada aparat berwenang."],"s":[2,3,1,4,5],"w":["Pasif.","Berisiko.","Ikut terpapar paham radikal.","Menjaga diri.","Menolak dan melapor."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2958,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Di media sosial ada ajakan menolak pemimpin daerah karena berbeda agama. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak ikut menyebarkan, dan bila menanggapi, mengingatkan dengan santun bahwa setiap warga negara berhak dipilih tanpa melihat agama.” Menjaga persatuan.\nPilihan terendah (nilai 1): “Ikut menyebarkan ajakan itu karena menurut Anda pemimpin sebaiknya satu agama dengan mayoritas warganya.” Diskriminatif.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menyembunyikan unggahan itu dari linimasa Anda.","Tidak menanggapi dan tidak menyebarkan.","Ikut menyebarkan ajakan itu karena menurut Anda pemimpin sebaiknya satu agama dengan mayoritas warganya.","Membaca tanpa menanggapi.","Tidak ikut menyebarkan, dan bila menanggapi, mengingatkan dengan santun bahwa setiap warga negara berhak dipilih tanpa melihat agama."],"s":[2,4,1,3,5],"w":["Menghindar.","Benar, pasif.","Diskriminatif.","Pasif.","Menjaga persatuan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2959,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang warga menyebarkan tuduhan tanpa bukti bahwa kelompok minoritas di desa merencanakan makar. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Meminta warga itu tidak menyebarkan tuduhan tanpa bukti, menenangkan warga lain, dan melaporkan bila ada indikasi nyata kepada aparat.” Mencegah fitnah dan konflik.\nPilihan terendah (nilai 1): “Ikut mengawasi rumah-rumah warga minoritas secara diam-diam karena menurut Anda lebih baik berjaga-jaga daripada kecolongan seperti di daerah lain.” Diskriminatif dan berbahaya.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Tidak ikut menyebarkan tuduhan itu.","Ikut mengawasi rumah-rumah warga minoritas secara diam-diam karena menurut Anda lebih baik berjaga-jaga daripada kecolongan seperti di daerah lain.","Menunggu kebenarannya terbukti.","Meminta warga itu tidak menyebarkan tuduhan tanpa bukti, menenangkan warga lain, dan melaporkan bila ada indikasi nyata kepada aparat.","Menjauhi warga itu."],"s":[4,1,3,5,2],"w":["Benar, pasif.","Diskriminatif dan berbahaya.","Pasif.","Mencegah fitnah dan konflik.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2960,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang rekan kerja mengatakan bahwa Pancasila bertentangan dengan agama. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan dengan santun bahwa Pancasila justru menjamin kehidupan beragama dan merupakan kesepakatan para pendiri bangsa, lalu mengajaknya berdiskusi.” Meluruskan dengan dialog.\nPilihan terendah (nilai 1): “Setuju dengannya dan menambahkan bahwa sila pertama sudah cukup sehingga sila lainnya tidak perlu.” Melemahkan ideologi negara.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Diam saja.","Menyatakan tidak setuju dengan pendapatnya.","Menjelaskan dengan santun bahwa Pancasila justru menjamin kehidupan beragama dan merupakan kesepakatan para pendiri bangsa, lalu mengajaknya berdiskusi.","Menghindari pembicaraan itu.","Setuju dengannya dan menambahkan bahwa sila pertama sudah cukup sehingga sila lainnya tidak perlu."],"s":[3,4,5,2,1],"w":["Pasif.","Tegas, kurang menjelaskan.","Meluruskan dengan dialog.","Menghindar.","Melemahkan ideologi negara."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2961,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Ada kelompok yang mengadakan pertemuan tertutup dan mengajarkan bahwa orang yang berbeda paham boleh diperangi. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak terlibat dan melaporkan informasi yang Anda ketahui kepada aparat berwenang.” Mencegah kekerasan.\nPilihan terendah (nilai 1): “Membela kelompok itu ketika warga mempersoalkannya, karena menurut Anda setiap kelompok berhak mengadakan pengajian apa pun.” Membenarkan ajaran kekerasan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Pura-pura tidak tahu.","Mencari tahu lebih jauh dengan ikut sekali.","Membela kelompok itu ketika warga mempersoalkannya, karena menurut Anda setiap kelompok berhak mengadakan pengajian apa pun.","Memperingatkan keluarga dan tetangga supaya tidak ikut.","Tidak terlibat dan melaporkan informasi yang Anda ketahui kepada aparat berwenang."],"s":[2,3,1,4,5],"w":["Abai.","Berisiko.","Membenarkan ajaran kekerasan.","Melindungi orang dekat.","Mencegah kekerasan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2962,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang teman lama mengirim tautan perekrutan untuk berangkat ke daerah konflik di luar negeri. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak membuka tautannya, menasihati teman itu, dan melaporkannya kepada aparat berwenang.” Mencegah perekrutan.\nPilihan terendah (nilai 1): “Menyimpan tautan itu dan menanyakan biaya keberangkatannya karena penasaran dengan janji penghidupan yang lebih baik di sana.” Terpapar perekrutan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menyimpan tautan itu dan menanyakan biaya keberangkatannya karena penasaran dengan janji penghidupan yang lebih baik di sana.","Tidak membuka tautannya, menasihati teman itu, dan melaporkannya kepada aparat berwenang.","Menolak dan memblokir kontaknya.","Menolak tanpa tindak lanjut.","Mengabaikan pesannya."],"s":[1,5,4,3,2],"w":["Terpapar perekrutan.","Mencegah perekrutan.","Menjaga diri.","Pasif.","Abai."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2963,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda mendengar rencana sekelompok pemuda menyerang rumah ibadah kelompok lain. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Segera melaporkannya kepada aparat keamanan dengan informasi yang jelas.” Mencegah kekerasan.\nPilihan terendah (nilai 1): “Membiarkan rencana itu karena menurut Anda kelompok itu memang sering membuat warga resah.” Membenarkan kekerasan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Membiarkan rencana itu karena menurut Anda kelompok itu memang sering membuat warga resah.","Memberi tahu tokoh masyarakat setempat.","Menasihati pemuda yang Anda kenal saja.","Segera melaporkannya kepada aparat keamanan dengan informasi yang jelas.","Diam karena takut."],"s":[1,4,3,5,2],"w":["Membenarkan kekerasan.","Membantu.","Tidak tuntas.","Mencegah kekerasan.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2964,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang warga meminta Anda menandatangani petisi untuk mengganti dasar negara. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dengan tegas dan menjelaskan bahwa Pancasila adalah dasar negara yang final dan mempersatukan bangsa.” Setia pada Pancasila.\nPilihan terendah (nilai 1): “Menandatangani petisi itu karena menurut Anda hanya bentuk aspirasi dan tidak akan berpengaruh apa-apa terhadap pekerjaan Anda.” Mendukung penggantian dasar negara.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menghindari warga itu.","Menandatangani petisi itu karena menurut Anda hanya bentuk aspirasi dan tidak akan berpengaruh apa-apa terhadap pekerjaan Anda.","Menolak menandatangani.","Menolak dengan tegas dan menjelaskan bahwa Pancasila adalah dasar negara yang final dan mempersatukan bangsa.","Mengatakan akan memikirkannya."],"s":[2,1,4,5,3],"w":["Menghindar.","Mendukung penggantian dasar negara.","Tegas.","Setia pada Pancasila.","Ragu."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2965,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Kelompok tertentu menyebarkan stiker bertuliskan ajakan menolak Bhinneka Tunggal Ika. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mendokumentasikan dan melaporkannya kepada aparat, lalu bersama warga menggiatkan kegiatan yang merawat kebersamaan.” Menjaga persatuan.\nPilihan terendah (nilai 1): “Menempelkan stiker itu di kendaraan Anda karena desainnya menarik dan menurut Anda hanya slogan biasa yang sedang ramai dibicarakan anak muda.” Ikut menyebarkan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menempelkan stiker itu di kendaraan Anda karena desainnya menarik dan menurut Anda hanya slogan biasa yang sedang ramai dibicarakan anak muda.","Melepas stiker itu dan melaporkannya.","Mendokumentasikan dan melaporkannya kepada aparat, lalu bersama warga menggiatkan kegiatan yang merawat kebersamaan.","Membiarkannya.","Melepas stiker itu tanpa melapor."],"s":[1,4,5,2,3],"w":["Ikut menyebarkan.","Tepat.","Menjaga persatuan.","Pasif.","Tidak tuntas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2966,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Ada anak muda di desa yang terkucil dan mulai rajin menonton video kekerasan berlatar ideologi. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mendekatinya, mengajaknya terlibat dalam kegiatan positif desa, dan melibatkan keluarga serta tokoh yang ia hormati.” Mencegah lewat rangkulan.\nPilihan terendah (nilai 1): “Menyebarkan cerita kepada warga bahwa ia calon teroris supaya semua orang waspada terhadapnya dan menjauhkan anak-anak mereka darinya.” Stigma yang mendorong radikalisasi.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menjauhinya.","Menyebarkan cerita kepada warga bahwa ia calon teroris supaya semua orang waspada terhadapnya dan menjauhkan anak-anak mereka darinya.","Memberi tahu keluarganya.","Mendekatinya, mengajaknya terlibat dalam kegiatan positif desa, dan melibatkan keluarga serta tokoh yang ia hormati.","Menunggu ia berubah sendiri."],"s":[2,1,4,5,3],"w":["Menghindar.","Stigma yang mendorong radikalisasi.","Membantu.","Mencegah lewat rangkulan.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2967,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Warga hendak menghakimi seseorang yang dituduh menistakan agama. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mencegah aksi main hakim sendiri, menenangkan warga, dan segera menghubungi aparat untuk memproses tuduhan itu secara hukum.” Menegakkan hukum dan mencegah kekerasan.\nPilihan terendah (nilai 1): “Ikut menghakimi karena menurut Anda orang itu memang pantas diberi pelajaran sebelum aparat datang, karena proses hukum sering berlarut-larut.” Main hakim sendiri.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Mencegah aksi main hakim sendiri, menenangkan warga, dan segera menghubungi aparat untuk memproses tuduhan itu secara hukum.","Pergi dari lokasi.","Menonton dari jauh.","Ikut menghakimi karena menurut Anda orang itu memang pantas diberi pelajaran sebelum aparat datang, karena proses hukum sering berlarut-larut.","Menghubungi aparat keamanan."],"s":[5,2,3,1,4],"w":["Menegakkan hukum dan mencegah kekerasan.","Menghindar.","Pasif.","Main hakim sendiri.","Tepat."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2968,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda diminta membimbing kegiatan kebangsaan untuk pelajar di daerah rawan konflik. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Merancang kegiatan interaktif yang mempertemukan pelajar dari berbagai latar belakang untuk bekerja sama.” Membangun persatuan.\nPilihan terendah (nilai 1): “Membagi pelajar ke dalam kelompok berdasarkan agama supaya tidak terjadi gesekan selama kegiatan berlangsung.” Memperkuat sekat.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Merancang kegiatan interaktif yang mempertemukan pelajar dari berbagai latar belakang untuk bekerja sama.","Membagikan modul bacaan.","Menyampaikan materi wawasan kebangsaan lewat ceramah.","Membagi pelajar ke dalam kelompok berdasarkan agama supaya tidak terjadi gesekan selama kegiatan berlangsung.","Menolak karena daerahnya rawan."],"s":[5,3,4,1,2],"w":["Membangun persatuan.","Seadanya.","Informatif, kurang interaktif.","Memperkuat sekat.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2969,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang guru mengajarkan bahwa menghormati simbol negara adalah perbuatan terlarang menurut agama. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikan keberatan lewat jalur sekolah dan dinas pendidikan, serta membantu siswa memahami makna penghormatan kepada simbol negara.” Meluruskan lewat jalur resmi.\nPilihan terendah (nilai 1): “Mendukung guru itu karena ia dikenal saleh dan disegani orang tua murid.” Membiarkan paham anti-negara.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Memindahkan anak Anda dari kelas itu tanpa melapor.","Menjelaskan kepada siswa yang Anda kenal bahwa ajaran itu keliru.","Menyampaikan keberatan lewat jalur sekolah dan dinas pendidikan, serta membantu siswa memahami makna penghormatan kepada simbol negara.","Membiarkannya.","Mendukung guru itu karena ia dikenal saleh dan disegani orang tua murid."],"s":[2,4,5,3,1],"w":["Menghindar.","Membantu sebagian.","Meluruskan lewat jalur resmi.","Pasif.","Membiarkan paham anti-negara."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2970,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Ada akun anonim yang menuduh instansi Anda melindungi kelompok tertentu dan mengajak orang menyerang kantor. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melaporkannya kepada humas dan aparat keamanan, lalu mendukung klarifikasi resmi.” Tanggap dan sesuai jalur.\nPilihan terendah (nilai 1): “Membalas akun itu dengan ancaman balik supaya pemiliknya takut dan berhenti menyerang instansi.” Memperkeruh.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Tidak masuk kerja karena takut.","Melaporkannya kepada humas dan aparat keamanan, lalu mendukung klarifikasi resmi.","Mengabaikannya.","Melaporkan akun itu ke platform.","Membalas akun itu dengan ancaman balik supaya pemiliknya takut dan berhenti menyerang instansi."],"s":[2,5,3,4,1],"w":["Menghindar.","Tanggap dan sesuai jalur.","Pasif.","Membantu.","Memperkeruh."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2971,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Sebuah keluarga di lingkungan Anda melarang anaknya bergaul dengan teman yang berbeda agama. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengajak keluarga itu berbincang tentang pentingnya pergaulan yang beragam, misalnya lewat kegiatan warga yang melibatkan anak-anak.” Menanamkan toleransi.\nPilihan terendah (nilai 1): “Mencontoh keluarga itu dengan melarang anak Anda bergaul dengan anak-anak yang berbeda keyakinan.” Intoleran.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Mengajak anak-anak bermain bersama dalam kegiatan warga.","Mencontoh keluarga itu dengan melarang anak Anda bergaul dengan anak-anak yang berbeda keyakinan.","Menghindari keluarga itu.","Membiarkannya.","Mengajak keluarga itu berbincang tentang pentingnya pergaulan yang beragam, misalnya lewat kegiatan warga yang melibatkan anak-anak."],"s":[4,1,2,3,5],"w":["Membangun kebersamaan.","Intoleran.","Menghindar.","Pasif.","Menanamkan toleransi."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2972,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang rekan mengajak Anda mengucilkan rekan lain yang berbeda aliran keagamaan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak ajakan itu dan tetap bersikap baik kepada semua rekan.” Menjaga persatuan.\nPilihan terendah (nilai 1): “Ikut mengucilkan karena tidak ingin dijauhi oleh kelompok rekan yang mengajak.” Intoleran.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Bersikap netral.","Menolak ajakan itu.","Menghindari kedua rekan.","Ikut mengucilkan karena tidak ingin dijauhi oleh kelompok rekan yang mengajak.","Menolak ajakan itu dan tetap bersikap baik kepada semua rekan."],"s":[3,4,2,1,5],"w":["Pasif.","Tepat.","Menghindar.","Intoleran.","Menjaga persatuan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2973,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda melihat bendera organisasi yang telah dibubarkan pemerintah dikibarkan di acara warga. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikan kepada panitia dengan santun bahwa organisasi itu sudah dibubarkan, dan melaporkannya kepada aparat bila tetap dikibarkan.” Tegas dan santun.\nPilihan terendah (nilai 1): “Ikut berfoto dengan bendera itu karena acaranya meriah dan banyak warga melakukannya.” Mendukung organisasi terlarang.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menyampaikan kepada panitia dengan santun bahwa organisasi itu sudah dibubarkan, dan melaporkannya kepada aparat bila tetap dikibarkan.","Melaporkannya kepada perangkat desa.","Membiarkannya.","Pulang lebih awal.","Ikut berfoto dengan bendera itu karena acaranya meriah dan banyak warga melakukannya."],"s":[5,4,3,2,1],"w":["Tegas dan santun.","Tepat.","Pasif.","Menghindar.","Mendukung organisasi terlarang."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2974,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Ada kampanye di kampus yang menyebut NKRI sebagai sistem yang harus diganti. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melaporkannya kepada pihak kampus dan mendukung diskusi kebangsaan yang meluruskan pandangan itu.” Menjaga NKRI lewat jalur yang benar.\nPilihan terendah (nilai 1): “Ikut menyebarkan materi kampanye karena menurut Anda kampus adalah tempat bebas berpendapat tentang apa saja.” Mendukung paham anti-NKRI.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Tidak mengikuti kampanye itu.","Melaporkannya kepada pihak kampus dan mendukung diskusi kebangsaan yang meluruskan pandangan itu.","Menghindari area kampanye.","Mendengarkan tanpa menanggapi.","Ikut menyebarkan materi kampanye karena menurut Anda kampus adalah tempat bebas berpendapat tentang apa saja."],"s":[4,5,2,3,1],"w":["Menjaga diri.","Menjaga NKRI lewat jalur yang benar.","Menghindar.","Pasif.","Mendukung paham anti-NKRI."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2975,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang kerabat mengaku senang dengan aksi bom bunuh diri di negara lain. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan dengan tenang bahwa membunuh orang tak bersalah tidak dibenarkan oleh ajaran mana pun, dan terus mengajaknya berdialog.” Meluruskan dan merangkul.\nPilihan terendah (nilai 1): “Ikut memuji aksi itu karena menurut Anda negara itu memang pantas mendapat balasan atas kebijakannya.” Membenarkan terorisme.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menjauhinya.","Diam saja.","Menyatakan tidak setuju.","Menjelaskan dengan tenang bahwa membunuh orang tak bersalah tidak dibenarkan oleh ajaran mana pun, dan terus mengajaknya berdialog.","Ikut memuji aksi itu karena menurut Anda negara itu memang pantas mendapat balasan atas kebijakannya."],"s":[2,3,4,5,1],"w":["Menghindar.","Pasif.","Tegas.","Meluruskan dan merangkul.","Membenarkan terorisme."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2976,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Ada pihak yang menawarkan bantuan dana untuk sekolah dengan syarat memasukkan kurikulum yang menolak Pancasila. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak bantuan itu dan melaporkannya kepada dinas pendidikan serta aparat terkait.” Menjaga pendidikan kebangsaan.\nPilihan terendah (nilai 1): “Menerima bantuan itu karena sekolah sangat membutuhkan dana dan kurikulumnya bisa diajarkan sebagian saja.” Mendukung paham anti-Pancasila.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menolak bantuan itu.","Meminta waktu untuk mempertimbangkan.","Menerima bantuan itu karena sekolah sangat membutuhkan dana dan kurikulumnya bisa diajarkan sebagian saja.","Menolak bantuan itu dan melaporkannya kepada dinas pendidikan serta aparat terkait.","Menyerahkan keputusan kepada pihak lain."],"s":[4,3,1,5,2],"w":["Tegas.","Ragu.","Mendukung paham anti-Pancasila.","Menjaga pendidikan kebangsaan.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2977,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Warga hendak mengusir keluarga terduga pelaku teror dari kampung. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menenangkan warga bahwa keluarga tidak otomatis bersalah, dan menyerahkan penanganan kepada aparat sambil memastikan keluarga itu aman.” Adil dan mencegah stigma.\nPilihan terendah (nilai 1): “Ikut mengusir keluarga itu karena khawatir kampung dicap sebagai sarang teroris oleh warga dari daerah lain dan anak-anak kampung jadi sulit diterima bekerja.” Tidak adil.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menghindari lokasi.","Menenangkan warga bahwa keluarga tidak otomatis bersalah, dan menyerahkan penanganan kepada aparat sambil memastikan keluarga itu aman.","Ikut mengusir keluarga itu karena khawatir kampung dicap sebagai sarang teroris oleh warga dari daerah lain dan anak-anak kampung jadi sulit diterima bekerja.","Menunggu keputusan warga.","Melaporkan situasi itu kepada aparat."],"s":[2,5,1,3,4],"w":["Menghindar.","Adil dan mencegah stigma.","Tidak adil.","Pasif.","Tepat."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2978,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Sekelompok orang menyebarkan kabar bahwa vaksin adalah alat musuh untuk melemahkan kelompok mereka. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Meluruskan dengan informasi dari sumber kesehatan resmi dan melibatkan tokoh yang dipercaya warga.” Melawan hoaks bernuansa kebencian.\nPilihan terendah (nilai 1): “Ikut menyebarkannya karena menurut Anda lebih baik waspada terhadap apa pun yang datang dari luar kelompok.” Menyebarkan hoaks dan kebencian.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Membiarkannya.","Tidak ikut menyebarkan kabar itu.","Ikut menyebarkannya karena menurut Anda lebih baik waspada terhadap apa pun yang datang dari luar kelompok.","Meluruskan dengan informasi dari sumber kesehatan resmi dan melibatkan tokoh yang dipercaya warga.","Menghindari pembicaraan itu."],"s":[3,4,1,5,2],"w":["Pasif.","Benar, pasif.","Menyebarkan hoaks dan kebencian.","Melawan hoaks bernuansa kebencian.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2979,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda menemukan grup daring yang membagikan cara merakit bahan peledak. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak menyebarkan apa pun, menyimpan bukti, dan segera melaporkannya kepada aparat berwenang.” Mencegah aksi teror.\nPilihan terendah (nilai 1): “Menyimpan materi itu karena penasaran dan menganggapnya sekadar pengetahuan kimia.” Berbahaya.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menyimpan materi itu karena penasaran dan menganggapnya sekadar pengetahuan kimia.","Keluar dari grup.","Tidak menyebarkan apa pun, menyimpan bukti, dan segera melaporkannya kepada aparat berwenang.","Tetap di grup tanpa berbuat apa-apa.","Keluar dari grup dan melaporkannya ke platform."],"s":[1,3,5,2,4],"w":["Berbahaya.","Menjaga diri.","Mencegah aksi teror.","Pasif.","Membantu."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2980,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang anak di lingkungan Anda dilarang ikut Pramuka karena dianggap tidak sesuai ajaran kelompok keluarganya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Berbincang dengan keluarganya tentang manfaat Pramuka bagi karakter dan kebersamaan anak, dengan bahasa yang menghormati keyakinan mereka.” Merangkul dengan santun.\nPilihan terendah (nilai 1): “Mencemooh keluarga itu di depan warga sebagai keluarga yang tertutup dan aneh.” Merendahkan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menghindari keluarga itu.","Berbincang dengan keluarganya tentang manfaat Pramuka bagi karakter dan kebersamaan anak, dengan bahasa yang menghormati keyakinan mereka.","Mencemooh keluarga itu di depan warga sebagai keluarga yang tertutup dan aneh.","Membiarkannya.","Mengajak anak itu ikut kegiatan anak-anak yang lain."],"s":[2,5,1,3,4],"w":["Menghindar.","Merangkul dengan santun.","Merendahkan.","Pasif.","Membangun kebersamaan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2981,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang penceramah tamu di kantor menyelipkan ajakan membenci kelompok lain. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melaporkannya kepada panitia dan pimpinan, serta mengusulkan seleksi narasumber yang lebih cermat.” Mencegah penyebaran kebencian di kantor.\nPilihan terendah (nilai 1): “Merekam ceramah itu dan menyebarkannya ke grup lain karena menurut Anda pesannya penting dan perlu didengar lebih banyak orang.” Ikut menyebarkan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Melaporkannya kepada panitia dan pimpinan, serta mengusulkan seleksi narasumber yang lebih cermat.","Diam saja.","Menyampaikan keberatan kepada panitia.","Meninggalkan acara.","Merekam ceramah itu dan menyebarkannya ke grup lain karena menurut Anda pesannya penting dan perlu didengar lebih banyak orang."],"s":[5,3,4,2,1],"w":["Mencegah penyebaran kebencian di kantor.","Pasif.","Tepat.","Menghindar.","Ikut menyebarkan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2982,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang rekan menolak bekerja sama dengan atasan baru karena berbeda agama. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengajaknya berdiskusi tentang profesionalisme dan kesetaraan di tempat kerja, dan mendorongnya bersikap terbuka.” Merangkul.\nPilihan terendah (nilai 1): “Mendukung sikapnya karena menurut Anda pemimpin sebaiknya berasal dari kelompok yang sama dengan mayoritas pegawai.” Diskriminatif.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Mengingatkannya bahwa ASN harus profesional.","Membiarkannya.","Menghindari membahasnya.","Mengajaknya berdiskusi tentang profesionalisme dan kesetaraan di tempat kerja, dan mendorongnya bersikap terbuka.","Mendukung sikapnya karena menurut Anda pemimpin sebaiknya berasal dari kelompok yang sama dengan mayoritas pegawai."],"s":[4,3,2,5,1],"w":["Tepat.","Pasif.","Menghindar.","Merangkul.","Diskriminatif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2983,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Unjuk rasa yang Anda saksikan mulai berubah menjadi ajakan merusak fasilitas umum. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjauh dari kerumunan, tidak terprovokasi, dan melaporkan provokator kepada aparat.” Menjaga ketertiban.\nPilihan terendah (nilai 1): “Ikut merusak karena menurut Anda tuntutan pengunjuk rasa benar dan pemerintah tidak mendengar.” Anarkis.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menonton dari dekat.","Menjauh dari kerumunan, tidak terprovokasi, dan melaporkan provokator kepada aparat.","Menjauh dari lokasi.","Merekam kejadian tanpa melapor.","Ikut merusak karena menurut Anda tuntutan pengunjuk rasa benar dan pemerintah tidak mendengar."],"s":[3,5,4,2,1],"w":["Berisiko.","Menjaga ketertiban.","Menjaga diri.","Pasif.","Anarkis."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2984,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda diminta merancang konten media sosial untuk melawan narasi radikal di kalangan remaja. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Membuat konten positif yang dekat dengan dunia remaja, dengan pesan persatuan dan rujukan yang benar, lalu mengevaluasi jangkauannya.” Kontra-narasi yang efektif.\nPilihan terendah (nilai 1): “Membuat konten yang menyerang kelompok tertentu dengan kasar supaya remaja takut bergabung.” Memperkeruh.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menyalin konten dari instansi lain.","Menunda karena tidak menguasai media sosial.","Membuat poster kebangsaan untuk diunggah.","Membuat konten positif yang dekat dengan dunia remaja, dengan pesan persatuan dan rujukan yang benar, lalu mengevaluasi jangkauannya.","Membuat konten yang menyerang kelompok tertentu dengan kasar supaya remaja takut bergabung."],"s":[3,2,4,5,1],"w":["Seadanya.","Menghindar.","Membantu.","Kontra-narasi yang efektif.","Memperkeruh."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2985,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang warga mengusulkan pembentukan satuan pengawas moral swasta yang boleh menghukum warga. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak usulan itu dan menjelaskan bahwa penegakan hukum hanya dilakukan aparat berwenang.” Menegakkan negara hukum.\nPilihan terendah (nilai 1): “Mendukung usulan itu karena menurut Anda aparat sering lamban dan warga perlu menjaga moral kampungnya sendiri.” Main hakim sendiri.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Bersikap netral.","Mendukung usulan itu karena menurut Anda aparat sering lamban dan warga perlu menjaga moral kampungnya sendiri.","Menyatakan keberatan.","Menolak usulan itu dan menjelaskan bahwa penegakan hukum hanya dilakukan aparat berwenang.","Tidak menghadiri pembahasan."],"s":[3,1,4,5,2],"w":["Pasif.","Main hakim sendiri.","Tepat.","Menegakkan negara hukum.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2986,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Beredar selebaran yang menyatakan pemilu haram dan mengancam warga yang ikut memilih. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melaporkannya kepada aparat dan penyelenggara pemilu, serta mengajak warga tetap menggunakan hak pilih.” Melindungi demokrasi.\nPilihan terendah (nilai 1): “Ikut membagikan selebaran itu karena menurut Anda pemilu tidak pernah membawa perubahan apa pun bagi rakyat kecil.” Mendukung ancaman terhadap demokrasi.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Ikut membagikan selebaran itu karena menurut Anda pemilu tidak pernah membawa perubahan apa pun bagi rakyat kecil.","Melaporkannya kepada aparat dan penyelenggara pemilu, serta mengajak warga tetap menggunakan hak pilih.","Melaporkan selebaran itu kepada perangkat desa.","Tidak datang ke TPS karena takut.","Membiarkannya."],"s":[1,5,4,2,3],"w":["Mendukung ancaman terhadap demokrasi.","Melindungi demokrasi.","Membantu.","Menghindar.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2987,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda mendapati dana sosial keagamaan di lingkungan Anda disalurkan kepada kelompok terlarang. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengumpulkan informasi yang Anda ketahui dan melaporkannya kepada aparat berwenang.” Memutus pendanaan terorisme.\nPilihan terendah (nilai 1): “Tetap menyumbang karena menurut Anda niatnya untuk ibadah dan penyalurannya bukan tanggung jawab penyumbang.” Ikut mendanai.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Pura-pura tidak tahu.","Tetap menyumbang karena menurut Anda niatnya untuk ibadah dan penyalurannya bukan tanggung jawab penyumbang.","Mengumpulkan informasi yang Anda ketahui dan melaporkannya kepada aparat berwenang.","Memberi tahu pengurus dana itu.","Berhenti menyumbang."],"s":[2,1,5,4,3],"w":["Abai.","Ikut mendanai.","Memutus pendanaan terorisme.","Membantu.","Menjaga diri."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2988,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Di sebuah forum, seseorang memuji ideologi yang ingin mengganti Pancasila dengan paham lain. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menanggapi dengan argumen tentang Pancasila sebagai dasar yang mempersatukan, dan melaporkan bila ada ajakan nyata untuk menggantinya.” Setia pada Pancasila.\nPilihan terendah (nilai 1): “Ikut memuji ideologi itu karena menurut Anda Pancasila sudah tidak menjawab persoalan zaman.” Mendukung penggantian dasar negara.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Ikut memuji ideologi itu karena menurut Anda Pancasila sudah tidak menjawab persoalan zaman.","Menanggapi dengan argumen tentang Pancasila sebagai dasar yang mempersatukan, dan melaporkan bila ada ajakan nyata untuk menggantinya.","Tidak menanggapi.","Keluar dari forum.","Menyatakan tidak setuju."],"s":[1,5,3,2,4],"w":["Mendukung penggantian dasar negara.","Setia pada Pancasila.","Pasif.","Menghindar.","Tegas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2989,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang anak di lingkungan Anda menggambar senjata dan mengatakan ingin memerangi tetangga yang berbeda keyakinan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Berbicara dengan lembut kepada anak dan keluarganya untuk mengetahui sumber pengaruhnya, lalu melibatkan sekolah atau konselor.” Mencegah sejak dini.\nPilihan terendah (nilai 1): “Menertawakan gambarnya dan menganggapnya lucu, lalu membagikannya ke grup warga.” Mengabaikan tanda bahaya.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menertawakan gambarnya dan menganggapnya lucu, lalu membagikannya ke grup warga.","Menghindari keluarga itu.","Memberi tahu orang tuanya.","Menganggapnya hanya imajinasi anak.","Berbicara dengan lembut kepada anak dan keluarganya untuk mengetahui sumber pengaruhnya, lalu melibatkan sekolah atau konselor."],"s":[1,2,4,3,5],"w":["Mengabaikan tanda bahaya.","Menghindar.","Membantu.","Pasif.","Mencegah sejak dini."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2990,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Ada kelompok yang menyebarkan peta \"negara baru\" dan mengajak sebuah daerah memisahkan diri dari NKRI. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak terlibat, mendokumentasikan, dan melaporkannya kepada aparat berwenang.” Menjaga keutuhan NKRI.\nPilihan terendah (nilai 1): “Ikut menyebarkan peta itu karena menurut Anda daerah itu memang kurang diperhatikan pemerintah pusat.” Mendukung separatisme.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Membiarkannya.","Tidak terlibat, mendokumentasikan, dan melaporkannya kepada aparat berwenang.","Ikut menyebarkan peta itu karena menurut Anda daerah itu memang kurang diperhatikan pemerintah pusat.","Tidak ikut menyebarkan.","Menghindari pembicaraan itu."],"s":[3,5,1,4,2],"w":["Pasif.","Menjaga keutuhan NKRI.","Mendukung separatisme.","Benar, pasif.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2991,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang pegawai baru menyatakan tidak mau mengucapkan sumpah setia kepada Pancasila saat pelantikan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melaporkannya kepada atasan dan bagian kepegawaian, karena kesetiaan kepada Pancasila adalah syarat menjadi ASN.” Menjaga integritas ASN.\nPilihan terendah (nilai 1): “Membelanya karena menurut Anda sumpah hanya formalitas dan yang penting ia bekerja dengan baik serta tidak pernah membuat masalah di kantor.” Melemahkan ideologi negara.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menasihatinya tentang kewajiban ASN.","Membelanya karena menurut Anda sumpah hanya formalitas dan yang penting ia bekerja dengan baik serta tidak pernah membuat masalah di kantor.","Membiarkannya.","Menghindari membahasnya.","Melaporkannya kepada atasan dan bagian kepegawaian, karena kesetiaan kepada Pancasila adalah syarat menjadi ASN."],"s":[4,1,3,2,5],"w":["Peduli.","Melemahkan ideologi negara.","Pasif.","Menghindar.","Menjaga integritas ASN."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2992,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Sebuah akun media sosial menyebarkan potongan ajaran yang ditafsirkan sepihak untuk membenarkan kekerasan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak menyebarkannya, melaporkan konten itu ke platform, dan membagikan penjelasan yang benar dari sumber yang kredibel.” Melawan narasi kekerasan.\nPilihan terendah (nilai 1): “Membagikan konten itu karena menurut Anda tafsirannya berani dan berbeda dari kebanyakan penceramah yang menurut Anda terlalu lunak.” Menyebarkan narasi kekerasan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Membagikan konten itu karena menurut Anda tafsirannya berani dan berbeda dari kebanyakan penceramah yang menurut Anda terlalu lunak.","Berhenti mengikuti akun itu.","Melaporkan konten itu ke platform.","Tidak menyebarkannya, melaporkan konten itu ke platform, dan membagikan penjelasan yang benar dari sumber yang kredibel.","Mengabaikannya."],"s":[1,2,4,5,3],"w":["Menyebarkan narasi kekerasan.","Menghindar.","Membantu.","Melawan narasi kekerasan.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2993,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Warga ingin menolak pembangunan rumah ibadah yang izinnya sudah lengkap dengan mengerahkan massa. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengajak warga menyampaikan keberatan lewat dialog yang difasilitasi aparat dan tokoh lintas agama, bukan lewat pengerahan massa.” Menjaga hak beribadah dan ketertiban.\nPilihan terendah (nilai 1): “Ikut dalam pengerahan massa karena menurut Anda suara mayoritas warga harus didengar.” Intoleran.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Ikut dalam pengerahan massa karena menurut Anda suara mayoritas warga harus didengar.","Mengajak warga menyampaikan keberatan lewat dialog yang difasilitasi aparat dan tokoh lintas agama, bukan lewat pengerahan massa.","Menunggu situasi.","Menghindari warga.","Melaporkan rencana pengerahan massa kepada aparat."],"s":[1,5,3,2,4],"w":["Intoleran.","Menjaga hak beribadah dan ketertiban.","Pasif.","Menghindar.","Mencegah."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2994,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang mahasiswa bertanya kepada Anda apakah membela negara bertentangan dengan agama. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan bahwa bela negara adalah kewajiban warga negara yang sejalan dengan nilai agama, dengan contoh dan rujukan yang tepat.” Mendidik.\nPilihan terendah (nilai 1): “Mengatakan bahwa agama lebih penting daripada negara sehingga bela negara boleh diabaikan bila bertentangan dengan keyakinan pribadi masing-masing.” Melemahkan semangat bela negara.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menjelaskan bahwa bela negara adalah kewajiban warga negara yang sejalan dengan nilai agama, dengan contoh dan rujukan yang tepat.","Menjawab singkat bahwa tidak bertentangan.","Menghindari pertanyaannya.","Mengatakan bahwa agama lebih penting daripada negara sehingga bela negara boleh diabaikan bila bertentangan dengan keyakinan pribadi masing-masing.","Menyarankannya membaca materi wawasan kebangsaan."],"s":[5,3,2,1,4],"w":["Mendidik.","Kurang menjelaskan.","Menghindar.","Melemahkan semangat bela negara.","Membantu."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2995,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda menemukan pegawai yang menyimpan materi propaganda kelompok terlarang di komputer kantor. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melaporkannya kepada atasan dan bagian keamanan informasi sesuai prosedur.” Tegas dan sesuai jalur.\nPilihan terendah (nilai 1): “Menyalin materi itu karena penasaran ingin membaca isinya di rumah dan memahami cara berpikir mereka.” Ikut menyimpan propaganda.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menyalin materi itu karena penasaran ingin membaca isinya di rumah dan memahami cara berpikir mereka.","Mengingatkan pegawai itu untuk menghapusnya.","Membiarkannya.","Melaporkannya kepada atasan dan bagian keamanan informasi sesuai prosedur.","Pura-pura tidak tahu."],"s":[1,4,3,5,2],"w":["Ikut menyimpan propaganda.","Peduli.","Pasif.","Tegas dan sesuai jalur.","Abai."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2996,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Sekelompok pemuda ingin membentuk laskar bersenjata tajam untuk menjaga kampung dari \"musuh agama\". Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak gagasan itu, menjelaskan bahwa keamanan adalah tugas aparat, dan mengajak pemuda ikut kegiatan siskamling yang resmi.” Mengarahkan ke kegiatan positif.\nPilihan terendah (nilai 1): “Mendukung gagasan itu karena menurut Anda warga memang perlu menjaga diri sendiri dari kelompok yang berbeda, apalagi aparat tidak selalu ada di kampung.” Mendukung kekerasan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Melaporkannya kepada perangkat desa.","Menolak gagasan itu, menjelaskan bahwa keamanan adalah tugas aparat, dan mengajak pemuda ikut kegiatan siskamling yang resmi.","Mendukung gagasan itu karena menurut Anda warga memang perlu menjaga diri sendiri dari kelompok yang berbeda, apalagi aparat tidak selalu ada di kampung.","Membiarkannya.","Menghindari pemuda itu."],"s":[4,5,1,3,2],"w":["Tepat.","Mengarahkan ke kegiatan positif.","Mendukung kekerasan.","Pasif.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2997,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda menjadi panitia peringatan Hari Lahir Pancasila di kantor. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Merancang kegiatan yang menarik dan melibatkan semua pegawai, misalnya diskusi kebangsaan dan lomba yang bermakna.” Menanamkan nilai Pancasila.\nPilihan terendah (nilai 1): “Memakai acara itu untuk kampanye kelompok tertentu.” Menyalahgunakan acara.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menyelenggarakan upacara sesuai susunan acara biasa.","Merancang kegiatan yang menarik dan melibatkan semua pegawai, misalnya diskusi kebangsaan dan lomba yang bermakna.","Mengikuti rancangan panitia lain.","Memakai acara itu untuk kampanye kelompok tertentu.","Mengundurkan diri dari kepanitiaan."],"s":[4,5,3,1,2],"w":["Bertanggung jawab.","Menanamkan nilai Pancasila.","Pasif.","Menyalahgunakan acara.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2998,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang anak tetangga pulang dari sebuah kelompok kajian dan menyebut orang tuanya kafir. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Membantu orang tuanya mendekati anak itu dengan sabar, mencari tahu ajaran yang diterima, dan melibatkan tokoh agama yang moderat.” Merangkul dan meluruskan.\nPilihan terendah (nilai 1): “Memarahi anak itu di depan warga supaya ia kapok.” Bisa membuatnya makin tertutup.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menghindari keluarga itu.","Memarahi anak itu di depan warga supaya ia kapok.","Membantu orang tuanya mendekati anak itu dengan sabar, mencari tahu ajaran yang diterima, dan melibatkan tokoh agama yang moderat.","Menasihati anak itu dengan baik.","Membiarkan keluarga itu menyelesaikan sendiri."],"s":[2,1,5,4,3],"w":["Menghindar.","Bisa membuatnya makin tertutup.","Merangkul dan meluruskan.","Peduli.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":2999,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang penulis di media daring menyebut kekerasan terhadap aparat sebagai perjuangan yang sah. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melaporkan tulisan itu kepada pengelola media dan pihak berwenang, serta tidak ikut menyebarkannya.” Melawan hasutan kekerasan.\nPilihan terendah (nilai 1): “Membagikan tulisan itu karena menurut Anda aparat memang sering bertindak sewenang-wenang terhadap rakyat kecil.” Menyebarkan hasutan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Melaporkan tulisan itu kepada pengelola media dan pihak berwenang, serta tidak ikut menyebarkannya.","Membaca tanpa menanggapi.","Membagikan tulisan itu karena menurut Anda aparat memang sering bertindak sewenang-wenang terhadap rakyat kecil.","Tidak membagikan tulisan itu.","Menghindari media itu."],"s":[5,3,1,4,2],"w":["Melawan hasutan kekerasan.","Pasif.","Menyebarkan hasutan.","Benar, pasif.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3000,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda diundang ke seminar yang pembicaranya mantan narapidana terorisme yang kini aktif mengampanyekan perdamaian. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Hadir untuk belajar dari pengalamannya tentang bahaya radikalisme dan cara mencegahnya.” Terbuka belajar.\nPilihan terendah (nilai 1): “Mengajak warga memboikot seminar itu karena menurut Anda mantan narapidana terorisme tidak layak didengar.” Stigma yang menghambat deradikalisasi.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Hadir untuk belajar dari pengalamannya tentang bahaya radikalisme dan cara mencegahnya.","Menolak hadir karena takut.","Hadir untuk mendengarkan.","Mengajak warga memboikot seminar itu karena menurut Anda mantan narapidana terorisme tidak layak didengar.","Mengirim perwakilan."],"s":[5,2,4,1,3],"w":["Terbuka belajar.","Menghindar.","Positif.","Stigma yang menghambat deradikalisasi.","Kurang terlibat."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3001,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang rekan menyebut ASN tidak wajib setia kepada pemerintah yang sah bila kebijakannya tidak ia sukai. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan bahwa ASN wajib setia kepada Pancasila, UUD 1945, NKRI, dan pemerintahan yang sah, dan bahwa perbedaan pendapat disampaikan lewat jalur yang benar.” Meluruskan dengan dasar yang jelas.\nPilihan terendah (nilai 1): “Setuju dengannya karena menurut Anda loyalitas hanya pantas diberikan kepada pemerintah yang Anda dukung.” Melanggar sumpah ASN.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Diam saja.","Menjelaskan bahwa ASN wajib setia kepada Pancasila, UUD 1945, NKRI, dan pemerintahan yang sah, dan bahwa perbedaan pendapat disampaikan lewat jalur yang benar.","Menghindari pembicaraan.","Menyatakan tidak setuju.","Setuju dengannya karena menurut Anda loyalitas hanya pantas diberikan kepada pemerintah yang Anda dukung."],"s":[3,5,2,4,1],"w":["Pasif.","Meluruskan dengan dasar yang jelas.","Menghindar.","Tegas.","Melanggar sumpah ASN."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3002,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Ada pesan berantai yang mengajak warga menimbun senjata untuk menghadapi \"kerusuhan\" yang akan datang. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak meneruskan pesan itu, menenangkan warga dengan informasi resmi, dan melaporkannya kepada aparat.” Mencegah kepanikan dan kekerasan.\nPilihan terendah (nilai 1): “Membeli senjata tajam untuk berjaga-jaga karena pesan itu terdengar meyakinkan dan banyak tetangga juga sudah membelinya.” Terprovokasi.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Keluar dari grup.","Tidak meneruskan pesan itu.","Membiarkannya.","Tidak meneruskan pesan itu, menenangkan warga dengan informasi resmi, dan melaporkannya kepada aparat.","Membeli senjata tajam untuk berjaga-jaga karena pesan itu terdengar meyakinkan dan banyak tetangga juga sudah membelinya."],"s":[2,4,3,5,1],"w":["Menghindar.","Benar, pasif.","Pasif.","Mencegah kepanikan dan kekerasan.","Terprovokasi."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3003,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Remaja di lingkungan Anda mudah terprovokasi konten kebencian di media sosial. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengadakan kegiatan literasi digital bersama tokoh pemuda supaya remaja bisa memilah konten dan berpikir kritis.” Pencegahan yang efektif.\nPilihan terendah (nilai 1): “Melarang semua remaja memakai media sosial dengan ancaman, karena menurut Anda itu cara paling cepat dan paling mudah diawasi orang tua.” Tidak efektif.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menasihati remaja yang Anda kenal.","Menganggap itu urusan sekolah.","Melarang semua remaja memakai media sosial dengan ancaman, karena menurut Anda itu cara paling cepat dan paling mudah diawasi orang tua.","Mengadakan kegiatan literasi digital bersama tokoh pemuda supaya remaja bisa memilah konten dan berpikir kritis.","Menyerahkan kepada orang tua masing-masing."],"s":[4,2,1,5,3],"w":["Membantu.","Menghindar.","Tidak efektif.","Pencegahan yang efektif.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3004,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Di grup alumni, seseorang membagikan konten yang menyebut kelompok lain sesat dan boleh dibunuh. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengingatkan bahwa konten itu menghasut kekerasan, meminta admin menghapusnya, dan melaporkannya ke platform.” Memutus hasutan.\nPilihan terendah (nilai 1): “Membiarkan dan menyukai unggahan itu karena pengunggahnya teman dekat Anda sejak kuliah dan Anda tidak ingin merusak pertemanan.” Membenarkan hasutan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Membiarkan dan menyukai unggahan itu karena pengunggahnya teman dekat Anda sejak kuliah dan Anda tidak ingin merusak pertemanan.","Mengingatkan bahwa konten itu menghasut kekerasan, meminta admin menghapusnya, dan melaporkannya ke platform.","Tidak menanggapi.","Meminta admin menghapusnya.","Keluar dari grup."],"s":[1,5,3,4,2],"w":["Membenarkan hasutan.","Memutus hasutan.","Pasif.","Tepat.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3005,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda mendengar khotbah di tempat umum yang menyerukan permusuhan terhadap warga negara asing tertentu yang tinggal di Indonesia. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melaporkannya kepada pengurus tempat itu dan aparat berwenang, karena hasutan kebencian dapat memicu kekerasan.” Mencegah kekerasan.\nPilihan terendah (nilai 1): “Ikut menyebarkan isi khotbah itu karena menurut Anda negara asal warga itu memang sudah lama bermusuhan dengan Indonesia.” Menyebarkan kebencian.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Melaporkannya kepada pengurus tempat itu dan aparat berwenang, karena hasutan kebencian dapat memicu kekerasan.","Ikut menyebarkan isi khotbah itu karena menurut Anda negara asal warga itu memang sudah lama bermusuhan dengan Indonesia.","Menyampaikan keberatan kepada pengurus.","Tidak menanggapi.","Pergi dari tempat itu."],"s":[5,1,4,3,2],"w":["Mencegah kekerasan.","Menyebarkan kebencian.","Tepat.","Pasif.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3006,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang warga negara asing menyebarkan ajaran yang menolak keberagaman di lingkungan Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melaporkannya kepada perangkat desa dan aparat yang mengawasi orang asing, serta mengingatkan warga untuk tidak terpengaruh.” Menjaga kebinekaan.\nPilihan terendah (nilai 1): “Ikut mengundangnya mengisi kegiatan warga karena ia dianggap berpengetahuan luas.” Ikut menyebarkan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Melaporkannya kepada perangkat desa dan aparat yang mengawasi orang asing, serta mengingatkan warga untuk tidak terpengaruh.","Ikut mengundangnya mengisi kegiatan warga karena ia dianggap berpengetahuan luas.","Menghindari warga itu.","Membiarkannya.","Mengingatkan warga untuk berhati-hati."],"s":[5,1,2,3,4],"w":["Menjaga kebinekaan.","Ikut menyebarkan.","Menghindar.","Pasif.","Membantu."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3007,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Sebuah organisasi kemasyarakatan di desa menyelenggarakan kegiatan kebangsaan dan meminta dukungan instansi. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mendukung sesuai aturan dan kemampuan instansi, misalnya dengan narasumber atau fasilitas, serta ikut hadir.” Memperkuat wawasan kebangsaan.\nPilihan terendah (nilai 1): “Meminta imbalan sebagai syarat dukungan.” Pungli.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Meminta imbalan sebagai syarat dukungan.","Menunggu keputusan pimpinan.","Meneruskan permintaan itu kepada atasan.","Mendukung sesuai aturan dan kemampuan instansi, misalnya dengan narasumber atau fasilitas, serta ikut hadir.","Menolak karena repot."],"s":[1,3,4,5,2],"w":["Pungli.","Pasif.","Prosedural.","Memperkuat wawasan kebangsaan.","Menutup peluang."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3008,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Dalam kegiatan kantor, ada usulan agar doa hanya dipimpin menurut satu agama dan agama lain tidak diberi tempat. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengusulkan doa bersama menurut keyakinan masing-masing atau doa yang dipimpin bergantian.” Inklusif.\nPilihan terendah (nilai 1): “Mendukung usulan itu karena pegawai yang berbeda keyakinan jumlahnya sedikit dan biasanya tidak keberatan.” Diskriminatif.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Tidak hadir.","Mengikuti keputusan panitia.","Mendukung usulan itu karena pegawai yang berbeda keyakinan jumlahnya sedikit dan biasanya tidak keberatan.","Menyampaikan keberatan kepada panitia.","Mengusulkan doa bersama menurut keyakinan masing-masing atau doa yang dipimpin bergantian."],"s":[2,3,1,4,5],"w":["Menghindar.","Pasif.","Diskriminatif.","Tepat.","Inklusif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3009,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Ada warga yang menolak hasil pemilu dengan mengajak melawan aparat secara fisik. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengingatkan bahwa keberatan atas hasil pemilu diselesaikan lewat jalur hukum, dan melaporkan ajakan kekerasan itu.” Menegakkan hukum.\nPilihan terendah (nilai 1): “Ikut dalam aksi itu karena menurut Anda hasil pemilunya memang curang dan jalur hukum terlalu lambat untuk mengubah keadaan.” Mendukung kekerasan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Ikut dalam aksi itu karena menurut Anda hasil pemilunya memang curang dan jalur hukum terlalu lambat untuk mengubah keadaan.","Tidak ikut dan menasihati warga.","Tidak menanggapi.","Mengingatkan bahwa keberatan atas hasil pemilu diselesaikan lewat jalur hukum, dan melaporkan ajakan kekerasan itu.","Menghindari warga itu."],"s":[1,4,3,5,2],"w":["Mendukung kekerasan.","Menjaga diri dan orang lain.","Pasif.","Menegakkan hukum.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3010,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang teman mengirim buku elektronik berisi panduan pindah ke wilayah yang dikuasai kelompok bersenjata. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak membaca lebih jauh, menasihati teman itu, dan melaporkan penyebarannya kepada aparat berwenang.” Mencegah perekrutan.\nPilihan terendah (nilai 1): “Meneruskan berkas itu ke teman lain yang menurut Anda sedang mencari makna hidup.” Ikut menyebarkan.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Meneruskan berkas itu ke teman lain yang menurut Anda sedang mencari makna hidup.","Mengabaikannya.","Menghapus berkas itu dan menasihati teman.","Tidak membaca lebih jauh, menasihati teman itu, dan melaporkan penyebarannya kepada aparat berwenang.","Menghapus berkas itu."],"s":[1,2,4,5,3],"w":["Ikut menyebarkan.","Pasif.","Menjaga diri dan teman.","Mencegah perekrutan.","Menjaga diri."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3011,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang rekan menyebut korban bom pantas mati karena berbeda keyakinan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menegaskan bahwa membunuh orang tak bersalah adalah kejahatan, mengingatkannya secara serius, dan melaporkannya bila ia terus menyebarkan pandangan itu.” Tegas melawan pembenaran teror.\nPilihan terendah (nilai 1): “Mengangguk setuju supaya tidak terjadi perdebatan di kantor.” Membenarkan terorisme.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menyatakan tidak setuju.","Diam saja.","Menjauhinya.","Menegaskan bahwa membunuh orang tak bersalah adalah kejahatan, mengingatkannya secara serius, dan melaporkannya bila ia terus menyebarkan pandangan itu.","Mengangguk setuju supaya tidak terjadi perdebatan di kantor."],"s":[4,3,2,5,1],"w":["Tegas.","Pasif.","Menghindar.","Tegas melawan pembenaran teror.","Membenarkan terorisme."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3012,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Sekelompok siswa di sekolah tempat Anda bertugas membentuk kelompok eksklusif yang menolak berteman dengan siswa lain. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengajak mereka terlibat dalam kegiatan bersama yang beragam dan berdialog dengan pembina tentang nilai kebersamaan.” Merangkul.\nPilihan terendah (nilai 1): “Membubarkan kelompok itu dengan keras di depan siswa lain, supaya mereka tahu sekolah tidak suka dengan kelompok seperti itu.” Bisa membuat mereka makin tertutup.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Mengajak mereka terlibat dalam kegiatan bersama yang beragam dan berdialog dengan pembina tentang nilai kebersamaan.","Melaporkannya kepada guru BK.","Membubarkan kelompok itu dengan keras di depan siswa lain, supaya mereka tahu sekolah tidak suka dengan kelompok seperti itu.","Membiarkannya.","Menghindari kelompok itu."],"s":[5,4,1,3,2],"w":["Merangkul.","Membantu.","Bisa membuat mereka makin tertutup.","Pasif.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3013,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda diminta mendampingi keluarga mantan narapidana terorisme yang ingin hidup normal. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mendampingi mereka mengakses layanan dan pekerjaan, sambil membangun penerimaan warga sekitar.” Mendukung reintegrasi.\nPilihan terendah (nilai 1): “Membocorkan identitas mereka kepada warga supaya warga berhati-hati dan tidak ada yang merasa dibohongi di kemudian hari.” Stigma dan pelanggaran privasi.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Mendampingi mereka mengakses layanan dan pekerjaan, sambil membangun penerimaan warga sekitar.","Menolak karena takut.","Menunggu permintaan mereka.","Membantu mengurus dokumen mereka.","Membocorkan identitas mereka kepada warga supaya warga berhati-hati dan tidak ada yang merasa dibohongi di kemudian hari."],"s":[5,2,3,4,1],"w":["Mendukung reintegrasi.","Menghindar.","Pasif.","Membantu.","Stigma dan pelanggaran privasi."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3014,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Ada spanduk yang menolak perayaan budaya daerah karena dianggap bertentangan dengan agama. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengajak tokoh agama dan tokoh adat berdialog supaya budaya daerah dan agama bisa hidup berdampingan.” Menjaga kerukunan.\nPilihan terendah (nilai 1): “Ikut memasang spanduk serupa karena menurut Anda budaya daerah harus tunduk sepenuhnya pada ajaran agama.” Intoleran.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Tidak menghadiri perayaan.","Melaporkan spanduk itu kepada perangkat desa.","Mengajak tokoh agama dan tokoh adat berdialog supaya budaya daerah dan agama bisa hidup berdampingan.","Membiarkannya.","Ikut memasang spanduk serupa karena menurut Anda budaya daerah harus tunduk sepenuhnya pada ajaran agama."],"s":[2,4,5,3,1],"w":["Menghindar.","Membantu.","Menjaga kerukunan.","Pasif.","Intoleran."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3015,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang pejabat lokal membiarkan kelompok intoleran menekan warga minoritas. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melaporkan kejadian itu lewat jalur pengaduan resmi dan lembaga yang berwenang, serta mendampingi warga minoritas mendapatkan perlindungan.” Membela hak warga.\nPilihan terendah (nilai 1): “Mendukung sikap pejabat itu supaya tidak terjadi keributan yang lebih besar di wilayahnya.” Membiarkan intoleransi.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menghindari masalah itu.","Menyampaikan keberatan kepada atasan.","Melaporkan kejadian itu lewat jalur pengaduan resmi dan lembaga yang berwenang, serta mendampingi warga minoritas mendapatkan perlindungan.","Diam karena takut.","Mendukung sikap pejabat itu supaya tidak terjadi keributan yang lebih besar di wilayahnya."],"s":[2,4,5,3,1],"w":["Menghindar.","Tepat.","Membela hak warga.","Pasif.","Membiarkan intoleransi."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3016,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Anda menemukan bahwa sebuah yayasan menyalurkan dana kepada keluarga pelaku teror untuk melanjutkan aksi. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengumpulkan informasi yang Anda ketahui dan melaporkannya kepada aparat berwenang.” Memutus pendanaan terorisme.\nPilihan terendah (nilai 1): “Ikut menyumbang karena yayasan itu mengaku hanya membantu anak yatim dan janda di daerah konflik.” Ikut mendanai.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Ikut menyumbang karena yayasan itu mengaku hanya membantu anak yatim dan janda di daerah konflik.","Pura-pura tidak tahu.","Membiarkannya.","Berhenti berhubungan dengan yayasan itu.","Mengumpulkan informasi yang Anda ketahui dan melaporkannya kepada aparat berwenang."],"s":[1,2,3,4,5],"w":["Ikut mendanai.","Abai.","Pasif.","Menjaga diri.","Memutus pendanaan terorisme."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3017,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Ada permainan daring yang dimodifikasi untuk menyebarkan propaganda kelompok teror. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melaporkannya kepada pengelola platform dan aparat, serta mengingatkan anak-anak dan orang tua di sekitar Anda.” Melindungi generasi muda.\nPilihan terendah (nilai 1): “Membagikan permainan itu karena menurut Anda hanya hiburan dan tidak akan memengaruhi anak-anak yang sudah besar.” Ikut menyebarkan propaganda.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menghapus permainan itu dari perangkat keluarga.","Membagikan permainan itu karena menurut Anda hanya hiburan dan tidak akan memengaruhi anak-anak yang sudah besar.","Melarang anak bermain gim tanpa penjelasan.","Melaporkannya kepada pengelola platform dan aparat, serta mengingatkan anak-anak dan orang tua di sekitar Anda.","Membiarkannya."],"s":[4,1,2,5,3],"w":["Melindungi keluarga.","Ikut menyebarkan propaganda.","Kurang efektif.","Melindungi generasi muda.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3018,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang rekan mengajak Anda ikut aksi yang menuntut penggantian dasar negara. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dengan tegas, mengingatkan kewajiban ASN untuk setia kepada Pancasila, dan melaporkannya bila ajakan itu terus berlanjut.” Setia dan tegas.\nPilihan terendah (nilai 1): “Ikut aksi itu karena menurut Anda tuntutannya hanya aspirasi dan tidak melanggar apa pun.” Mendukung penggantian dasar negara.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Menghindarinya.","Menolak dengan tegas, mengingatkan kewajiban ASN untuk setia kepada Pancasila, dan melaporkannya bila ajakan itu terus berlanjut.","Ikut aksi itu karena menurut Anda tuntutannya hanya aspirasi dan tidak melanggar apa pun.","Mengatakan akan memikirkannya.","Menolak ajakan itu."],"s":[2,5,1,3,4],"w":["Menghindar.","Setia dan tegas.","Mendukung penggantian dasar negara.","Ragu.","Tegas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3019,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Warga desa menolak pendatang karena khawatir mereka membawa paham radikal, tanpa bukti apa pun. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengingatkan warga agar tidak berprasangka, menyambut pendatang secara wajar, dan melapor hanya bila ada indikasi nyata.” Adil dan waspada secara proporsional.\nPilihan terendah (nilai 1): “Ikut menolak dan mengawasi pendatang itu secara berlebihan karena menurut Anda lebih baik mencegah daripada mengobati, walaupun belum ada bukti apa pun.” Diskriminatif.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Mengingatkan warga agar tidak berprasangka, menyambut pendatang secara wajar, dan melapor hanya bila ada indikasi nyata.","Bersikap netral.","Ikut menolak dan mengawasi pendatang itu secara berlebihan karena menurut Anda lebih baik mencegah daripada mengobati, walaupun belum ada bukti apa pun.","Menyambut pendatang itu dengan ramah.","Menghindari pendatang itu."],"s":[5,3,1,4,2],"w":["Adil dan waspada secara proporsional.","Pasif.","Diskriminatif.","Positif.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3020,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Seorang pengguna media sosial menyebarkan teori bahwa semua bencana adalah azab bagi kelompok tertentu. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak menyebarkannya dan, bila menanggapi, meluruskan dengan santun bahwa bencana tidak boleh dipakai untuk menyudutkan kelompok mana pun.” Menjaga persatuan.\nPilihan terendah (nilai 1): “Ikut menyebarkan unggahan itu karena menurut Anda banyak orang setuju dengannya.” Menyebarkan kebencian.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Tidak menyebarkannya dan, bila menanggapi, meluruskan dengan santun bahwa bencana tidak boleh dipakai untuk menyudutkan kelompok mana pun.","Membaca komentar-komentarnya.","Ikut menyebarkan unggahan itu karena menurut Anda banyak orang setuju dengannya.","Berhenti mengikuti akun itu.","Tidak menanggapi."],"s":[5,3,1,2,4],"w":["Menjaga persatuan.","Pasif.","Menyebarkan kebencian.","Menghindar.","Benar, pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3021,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Teman Anda mengatakan bahwa toleransi berarti mengorbankan keyakinan sendiri, sehingga ia menolak bergaul dengan orang yang berbeda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan bahwa toleransi berarti menghormati keyakinan orang lain tanpa harus mengubah keyakinan sendiri, dan mengajaknya bergaul secara wajar.” Meluruskan konsep toleransi.\nPilihan terendah (nilai 1): “Setuju dengannya karena menurut Anda bergaul dengan orang berbeda keyakinan memang berisiko melemahkan iman.” Intoleran.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Setuju dengannya karena menurut Anda bergaul dengan orang berbeda keyakinan memang berisiko melemahkan iman.","Membiarkannya.","Menjelaskan bahwa toleransi berarti menghormati keyakinan orang lain tanpa harus mengubah keyakinan sendiri, dan mengajaknya bergaul secara wajar.","Menghindari pembicaraan itu.","Menyatakan tidak setuju dengan pandangannya."],"s":[1,3,5,2,4],"w":["Intoleran.","Pasif.","Meluruskan konsep toleransi.","Menghindar.","Tegas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."},{"i":3022,"k":"skd.tkp.anti-radikalisme","j":"situasi","v":2,"q":"Dalam kerja bakti desa, sekelompok warga menolak bekerja bersama warga yang berbeda keyakinan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengajak semua warga bekerja bersama dengan mengingatkan bahwa gotong royong adalah milik bersama.” Merawat kebersamaan.\nPilihan terendah (nilai 1): “Mengikuti kemauan kelompok itu dan memisahkan pembagian tugas berdasarkan keyakinan warga supaya kerja bakti tetap berjalan tanpa keributan.” Memperkuat sekat.\nPrinsip aspek anti-radikalisme: Setia pada Pancasila, UUD NRI 1945, NKRI, dan Bhinneka Tunggal Ika; tolak kekerasan dan intoleransi lewat dialog, merangkul, dan melapor kepada pihak berwenang.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri.","o":["Mengajak semua warga bekerja bersama dengan mengingatkan bahwa gotong royong adalah milik bersama.","Membiarkan mereka bekerja terpisah.","Tidak ikut kerja bakti.","Membagi tugas dengan mencampur warga dari berbagai latar belakang.","Mengikuti kemauan kelompok itu dan memisahkan pembagian tugas berdasarkan keyakinan warga supaya kerja bakti tetap berjalan tanpa keributan."],"s":[5,3,2,4,1],"w":["Merawat kebersamaan.","Pasif.","Menghindar.","Membangun kebersamaan.","Memperkuat sekat."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: dialog, meluruskan dengan rujukan yang benar, merangkul, melapor kepada pihak berwenang. Waspadai ikut menyebarkan, membenarkan kekerasan, dan main hakim sendiri."}];
